#include <stdio.h>   // For FILE, NULL, EOF, fdopen, fputs, fclose
#include <stdlib.h>  // For malloc, free
#include <string.h>  // For strlen, strcpy
#include <unistd.h>  // For close, mkstemp, unlink (explicitly for POSIX systems)

/**
Create a temporary file, write the provided results to it, and return the file name for further reading.

@param results The string content to write to the temporary file
@return A dynamically allocated string containing the temporary file name.
 */
char* write_results(const char* results); // Function declaration

char* write_results(const char* results) {
    // Define a template for the temporary file name.
    // mkstemp requires the template to be mutable and have at least 6 'X's.
    // These 'X's will be replaced by a unique sequence.
    // We use a buffer on the stack for this. A common temporary directory
    // on POSIX systems is /tmp.
    char temp_filename_template[] = "/tmp/results_XXXXXX";

    // mkstemp modifies the template in place, so we need a mutable copy
    // of the template string. The size of temp_filename_template is
    // known at compile time.
    char temp_path_buffer[sizeof(temp_filename_template)];
    strcpy(temp_path_buffer, temp_filename_template);

    // Create and open the temporary file securely.
    // mkstemp returns a file descriptor (int) and modifies temp_path_buffer
    // to contain the actual unique file name.
    int fd = mkstemp(temp_path_buffer);
    if (fd == -1) {
        // Failed to create temporary file.
        return NULL;
    }

    // Convert the file descriptor to a FILE* stream for easier writing with fputs.
    // "w" mode truncates the file to zero length or creates it for writing.
    // Since mkstemp already created it, "w" is appropriate.
    FILE* temp_file = fdopen(fd, "w");
    if (temp_file == NULL) {
        // Failed to open file stream. Close the underlying file descriptor.
        close(fd); // From unistd.h
        // CRITICAL FIX: Unlink the temporary file as its name cannot be returned.
        unlink(temp_path_buffer);
        return NULL;
    }

    // Write the provided results string to the temporary file.
    // fputs returns EOF on error, a non-negative value on success.
    if (fputs(results, temp_file) == EOF) {
        // Failed to write to file. Close the file stream.
        fclose(temp_file);
        // CRITICAL FIX: Unlink the temporary file as the write operation failed.
        unlink(temp_path_buffer);
        return NULL;
    }

    // Close the file stream. This flushes any buffered data and
    // closes the underlying file descriptor.
    fclose(temp_file);

    // Dynamically allocate memory for the file name to be returned.
    // The caller is responsible for freeing this memory using free().
    char* filename_to_return = (char*)malloc(strlen(temp_path_buffer) + 1);
    if (filename_to_return == NULL) {
        // Failed to allocate memory.
        // The temporary file has been created and closed, but we cannot
        // return its name to the caller.
        // CRITICAL FIX: Unlink the temporary file as its name cannot be returned.
        unlink(temp_path_buffer);
        return NULL;
    }

    // Copy the generated unique temporary file name into the allocated memory.
    strcpy(filename_to_return, temp_path_buffer);

    // Return the dynamically allocated file name.
    return filename_to_return;
}
```

